import{_ as t,o as d,c as o,a6 as r}from"./chunks/framework.Dtv7txdI.js";const u=JSON.parse('{"title":"Lua API Types","description":"","frontmatter":{},"headers":[],"relativePath":"v1/api/types.md","filePath":"v1/api/types.md","lastUpdated":1787648967000}'),a={name:"v1/api/types.md"};function s(c,e,n,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="lua-api-types" tabindex="-1">Lua API Types <a class="header-anchor" href="#lua-api-types" aria-label="Permalink to “Lua API Types”">​</a></h1><p>The objects the <a href="./index"><code>nitr.*</code> functions</a> hand you. Every one is covered by the generated <code>nitr-types.lua</code> completions, so your editor knows all of this too.</p><h2 id="nitr-request" tabindex="-1"><code>nitr.Request</code> <a class="header-anchor" href="#nitr-request" aria-label="Permalink to “nitr.Request”">​</a></h2><p>The incoming request, passed to every handler and middleware. See <a href="./../server/requests">Requests</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>method</code></td><td><code>string</code></td><td>Request method, uppercase (<code>&quot;GET&quot;</code>).</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>URI path (<code>&quot;/users/42&quot;</code>).</td></tr><tr><td><code>params</code></td><td><code>table&lt;string, string&gt;</code></td><td>Path parameters captured by the router (<code>:id</code> → <code>params.id</code>).</td></tr><tr><td><code>query</code></td><td><code>table&lt;string, string&gt;</code></td><td>Parsed query string; repeated keys keep the last value.</td></tr><tr><td><code>headers</code></td><td><code>table&lt;string, string&gt;</code></td><td>Request headers, <strong>lowercase names</strong>.</td></tr><tr><td><code>id</code></td><td><code>string</code></td><td>The request id (UUIDv7, echoed as <code>X-Request-ID</code>).</td></tr><tr><td><code>remote_addr</code></td><td><code>string</code></td><td>Peer address (<code>&quot;ip:port&quot;</code>).</td></tr><tr><td><code>uri</code></td><td><code>table</code></td><td>URI components: <code>scheme</code>, <code>host</code>, <code>port</code>, <code>path</code>, <code>authority</code>, <code>query</code>.</td></tr><tr><td><code>cookies</code></td><td><a href="#nitr-requestcookies"><code>nitr.RequestCookies</code></a></td><td>Parsed request cookies.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:json() -&gt; table</code></td><td>Reads and decodes the body as JSON. Errors on an empty or invalid body.</td></tr><tr><td><code>:text() -&gt; string</code></td><td>Reads the whole body as a string.</td></tr><tr><td><code>:form() -&gt; table&lt;string, string&gt;</code></td><td>Reads an <code>application/x-www-form-urlencoded</code> body as a table. The parse is cached, so middleware and handler can both call it.</td></tr><tr><td><code>:multipart(fn) -&gt; integer</code></td><td>Invokes <code>fn(part)</code> once per part of a <code>multipart/form-data</code> body, in arrival order; returns the part count. Needs the <code>multipart</code> Cargo feature.</td></tr><tr><td><code>:read(n?) -&gt; string|nil</code></td><td>Streams the body: the next chunk as it arrives, or at least <code>n</code> bytes. <code>nil</code> marks the end.</td></tr><tr><td><code>:accepts(...) -&gt; string|nil</code></td><td>The best match among the given media types for the <code>Accept</code> header, or <code>nil</code>.</td></tr><tr><td><code>:fresh(etag, last_modified?) -&gt; boolean</code></td><td>Whether the client&#39;s cached copy is current, per <code>If-None-Match</code> / <code>If-Modified-Since</code>.</td></tr></tbody></table><h2 id="nitr-requestcookies" tabindex="-1"><code>nitr.RequestCookies</code> <a class="header-anchor" href="#nitr-requestcookies" aria-label="Permalink to “nitr.RequestCookies”">​</a></h2><p>Cookies from the <code>Cookie</code> header. Index by name: <code>req.cookies.session</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:verify(name, secret) -&gt; string|nil</code></td><td>The verified value of a signed cookie, or <code>nil</code> when missing <strong>or</strong> tampered.</td></tr></tbody></table><p>See <a href="./../server/cookies-sessions">Cookies &amp; sessions</a>.</p><h2 id="nitr-response" tabindex="-1"><code>nitr.Response</code> <a class="header-anchor" href="#nitr-response" aria-label="Permalink to “nitr.Response”">​</a></h2><p>A response: <code>{ status, headers, body }</code> plus a cookie builder. The helpers build these; handlers may also build them by hand. See <a href="./../server/responses">Responses</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>integer</code></td><td>HTTP status code. Default <code>200</code>.</td></tr><tr><td><code>headers</code></td><td><code>table</code></td><td>Response headers. A value may be a string, an integer, or an array of strings.</td></tr><tr><td><code>body</code></td><td><code>string | fun(...) | nil</code></td><td>Body string, or a <a href="./../server/streaming">streaming body</a> function.</td></tr><tr><td><code>cookies</code></td><td><a href="#nitr-responsecookies"><code>nitr.ResponseCookies</code></a></td><td><code>Set-Cookie</code> builder, attached by the helpers.</td></tr></tbody></table><h2 id="nitr-responsecookies" tabindex="-1"><code>nitr.ResponseCookies</code> <a class="header-anchor" href="#nitr-responsecookies" aria-label="Permalink to “nitr.ResponseCookies”">​</a></h2><p>Builder for <code>Set-Cookie</code> headers on a response.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:set(name, value, opts?)</code></td><td>Adds a cookie. Options: <code>http_only</code>, <code>secure</code>, <code>path</code>, <code>domain</code>, <code>max_age</code> (seconds), <code>same_site</code> (<code>&quot;Strict&quot;</code> / <code>&quot;Lax&quot;</code> / <code>&quot;None&quot;</code>).</td></tr><tr><td><code>:set_signed(name, value, secret, opts?)</code></td><td>Adds an HMAC-signed cookie, verifiable later with <code>req.cookies:verify</code>.</td></tr></tbody></table><h2 id="nitr-app" tabindex="-1"><code>nitr.App</code> <a class="header-anchor" href="#nitr-app" aria-label="Permalink to “nitr.App”">​</a></h2><p>The application: routes, middleware, error handling, static mounts. Return it from the handler script. See <a href="./../server/routing">Routing</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:get(path, ...)</code></td><td>Registers a GET route: <code>middleware..., handler</code>, plus an optional trailing <code>{ on_error = fn }</code>. Paths take <code>:name</code> parameters and a trailing <code>*</code> catch-all.</td></tr><tr><td><code>:post(path, ...)</code></td><td>Registers a POST route (see <code>get</code>).</td></tr><tr><td><code>:put(path, ...)</code></td><td>Registers a PUT route (see <code>get</code>).</td></tr><tr><td><code>:delete(path, ...)</code></td><td>Registers a DELETE route (see <code>get</code>).</td></tr><tr><td><code>:patch(path, ...)</code></td><td>Registers a PATCH route (see <code>get</code>).</td></tr><tr><td><code>:head(path, ...)</code></td><td>Registers a HEAD route. Without one, HEAD reuses the GET route with the body stripped.</td></tr><tr><td><code>:options(path, ...)</code></td><td>Registers an OPTIONS route. Without one, OPTIONS answers <code>204</code> with <code>Allow</code>.</td></tr><tr><td><code>:use(mw)</code></td><td>Adds app-wide middleware: a factory <code>fn(next) -&gt; fn(req)</code>. <strong>Must be called before any route.</strong></td></tr><tr><td><code>:on_error(handler)</code></td><td>Sets the app-wide error handler: <code>fn(err, req)</code>, where <code>err</code> is the <a href="./../server/errors#the-error-value">structured error</a>.</td></tr><tr><td><code>:static(mount, dir, opts?)</code></td><td>Mounts a static directory, served in Rust. Options: <code>{ spa = boolean, cache_control = string }</code>.</td></tr></tbody></table><h2 id="nitr-part" tabindex="-1"><code>nitr.Part</code> <a class="header-anchor" href="#nitr-part" aria-label="Permalink to “nitr.Part”">​</a></h2><p>One part of a multipart upload, delivered to the <code>req:multipart</code> callback. See <a href="./../server/requests#file-uploads">Requests → File uploads</a>.</p><table tabindex="0"><thead><tr><th>Field / method</th><th>Description</th></tr></thead><tbody><tr><td><code>name: string|nil</code></td><td>Form field name.</td></tr><tr><td><code>filename: string|nil</code></td><td>Client-supplied file name. <strong>Never trust it</strong> — run it through <code>nitr.path.basename</code>.</td></tr><tr><td><code>content_type: string|nil</code></td><td>Part content type.</td></tr><tr><td><code>:text() -&gt; string</code></td><td>Reads a non-file field as a string, bounded by <code>[limits] max_field_bytes</code>.</td></tr><tr><td><code>:save(path) -&gt; integer</code></td><td>Streams a file part to <code>path</code> without entering the Lua heap; returns bytes written.</td></tr><tr><td><code>:discard()</code></td><td>Drains and drops the part.</td></tr></tbody></table><h2 id="nitr-fetchhandle" tabindex="-1"><code>nitr.FetchHandle</code> <a class="header-anchor" href="#nitr-fetchhandle" aria-label="Permalink to “nitr.FetchHandle”">​</a></h2><p>An <strong>unsent</strong> outbound request from <code>nitr.fetch</code>. Send it, or hand it to <code>nitr.await_all</code>. See <a href="./../server/fetch">Outbound HTTP</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:send() -&gt; nitr.FetchResponse</code></td><td>Performs the request.</td></tr></tbody></table><h2 id="nitr-fetchresponse" tabindex="-1"><code>nitr.FetchResponse</code> <a class="header-anchor" href="#nitr-fetchresponse" aria-label="Permalink to “nitr.FetchResponse”">​</a></h2><p>An outbound response.</p><table tabindex="0"><thead><tr><th>Field / method</th><th>Description</th></tr></thead><tbody><tr><td><code>status: integer</code></td><td>HTTP status code.</td></tr><tr><td><code>headers: table&lt;string, string&gt;</code></td><td>Response headers.</td></tr><tr><td><code>url: string</code></td><td>Final URL <strong>after redirects</strong>.</td></tr><tr><td><code>:text() -&gt; string</code></td><td>The body as a string, bounded by <code>[fetch] max_response_bytes</code>.</td></tr><tr><td><code>:json() -&gt; table</code></td><td>The body decoded as JSON.</td></tr><tr><td><code>:read() -&gt; string|nil</code></td><td>Streams the body chunk by chunk; <code>nil</code> at the end.</td></tr></tbody></table><h2 id="nitr-schema" tabindex="-1"><code>nitr.Schema</code> <a class="header-anchor" href="#nitr-schema" aria-label="Permalink to “nitr.Schema”">​</a></h2><p>A compiled validation schema from <code>nitr.validate.schema</code>. See <a href="./../server/validation">Validation</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:check(value) -&gt; table|nil, table|nil</code></td><td>Validates a value. Returns the data (<strong>declared fields only</strong>), or <code>nil</code> plus <code>{ message, fields }</code> mapping each failing path to its message.</td></tr></tbody></table><h2 id="nitr-session" tabindex="-1"><code>nitr.Session</code> <a class="header-anchor" href="#nitr-session" aria-label="Permalink to “nitr.Session”">​</a></h2><p>A stateless signed-cookie session from <code>nitr.session</code>. Assign fields directly (<code>session.user_id = 42</code>). See <a href="./../server/cookies-sessions#sessions">Sessions</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>:save(resp)</code></td><td>Serializes the session into a signed cookie on the response. An empty session <strong>deletes</strong> the cookie.</td></tr><tr><td><code>:clear()</code></td><td>Removes every field; <code>save</code> then writes the deletion cookie.</td></tr></tbody></table><h2 id="nitr-tx" tabindex="-1"><code>nitr.Tx</code> <a class="header-anchor" href="#nitr-tx" aria-label="Permalink to “nitr.Tx”">​</a></h2><p>A database transaction handle inside <code>nitr.db:transaction</code>. Same query API as <a href="./index#nitr-db"><code>nitr.db</code></a> — <code>execute</code>, <code>query</code>, <code>query_row</code>, <code>query_one</code> — plus nesting via savepoints.</p><div class="warning custom-block github-alert"><p class="custom-block-title">Use `tx`, not the outer `nitr.db`</p><p></p><p>The outer handle refuses to run while a transaction is open, rather than silently joining it. See <a href="./../server/database#transactions">Database → Transactions</a>.</p></div><h2 id="the-error-table" tabindex="-1">The error table <a class="header-anchor" href="#the-error-table" aria-label="Permalink to “The error table”">​</a></h2><p>Not a named type, but the shape every <code>on_error</code> handler and <code>nitr.errinfo</code> produces:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>One of <code>&quot;lua&quot;</code>, <code>&quot;nitr&quot;</code>, <code>&quot;module&quot;</code>, <code>&quot;timeout&quot;</code>, <code>&quot;memory&quot;</code>, <code>&quot;panic&quot;</code>. A <strong>closed set</strong> — branch on this, never on <code>message</code>.</td></tr><tr><td><code>message</code></td><td>The failure message.</td></tr><tr><td><code>source</code></td><td>The failing chunk, when known.</td></tr><tr><td><code>line</code></td><td>The failing line, when known.</td></tr><tr><td><code>module</code></td><td>The failing module, when attributed.</td></tr><tr><td><code>traceback</code></td><td>Bounded Lua call stack, innermost first.</td></tr><tr><td><code>cause</code></td><td>Bounded underlying Rust error chain.</td></tr></tbody></table><p>See <a href="./../server/errors#the-error-value">Errors</a>.</p>',41)])])}const b=t(a,[["render",s]]);export{u as __pageData,b as default};
